import{c as a,Q as s,j as t,m as o}from"./chunks/framework.7r1mYKiJ.js";const m=JSON.parse('{"title":"Messages & Chat Formatting","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/messages.md","filePath":"configuration/messages.md"}'),i={name:"configuration/messages.md"};function r(l,e,n,d,c,h){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="messages-chat-formatting" tabindex="-1">Messages &amp; Chat Formatting <a class="header-anchor" href="#messages-chat-formatting" aria-label="Permalink to &quot;Messages &amp; Chat Formatting&quot;">​</a></h1><p>AetherUHC allows you to completely customize every player-facing message, title, and chat format in the plugin. These messages are defined in your <code>Language.java</code> enum, and are serialized to the <code>lang.yml</code> or <code>uhcconfiguration.yml</code> file upon startup.</p><h2 id="formatting-codes" tabindex="-1">Formatting Codes <a class="header-anchor" href="#formatting-codes" aria-label="Permalink to &quot;Formatting Codes&quot;">​</a></h2><p>AetherUHC supports both standard Bukkit color codes (<code>&amp;</code>) and modern hexadecimal colors (<code>#HEX</code>).</p><h3 id="standard-colors" tabindex="-1">Standard Colors <a class="header-anchor" href="#standard-colors" aria-label="Permalink to &quot;Standard Colors&quot;">​</a></h3><p>Use the <code>&amp;</code> symbol followed by a character (0-9, a-f) to format text for older Minecraft versions:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PREFIX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&amp;3Aether &amp;8»&amp;r &quot;</span></span></code></pre></div><h3 id="hex-colors-1-16" tabindex="-1">HEX Colors (1.16+) <a class="header-anchor" href="#hex-colors-1-16" aria-label="Permalink to &quot;HEX Colors (1.16+)&quot;">​</a></h3><p>If your server is running Minecraft 1.16 or newer, you can use high-resolution HEX colors to create seamless gradients and vibrant themes.</p><p>Use the format <code>&amp;#&lt;hexcode&gt;</code> to apply a hex color:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PREFIX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&amp;#03D1EBAether &amp;#467780»&amp;r &quot;</span></span></code></pre></div><h2 id="modifying-messages" tabindex="-1">Modifying Messages <a class="header-anchor" href="#modifying-messages" aria-label="Permalink to &quot;Modifying Messages&quot;">​</a></h2><p>To change a message:</p><ol><li>Open your <code>plugins/AetherUHC/uhcconfiguration.yml</code> (or <code>lang.yml</code> if configured separately).</li><li>Locate the message you want to change (e.g., <code>DEATH_MESSAGE</code>).</li><li>Modify the string. Note that some strings contain internal variables like <code>&lt;player&gt;</code> or <code>&lt;killer&gt;</code> which are parsed dynamically.</li><li>Save the file and type <code>/aetheruhc reload</code> in-game to apply the changes immediately.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Do not remove placeholders like <code>&lt;player&gt;</code> from essential messages, as this will break the context of the broadcast!</p></div>',15)])])}const g=a(i,[["render",r]]);export{m as __pageData,g as default};
